INSERT INTO public.vehicle_brands (name_fa,name_en,slug,normalized_name,is_active,sort_order)
VALUES
('برلیانس','Brilliance','brilliance','برلیانس',true,0),
('بسترن','Besturn','besturn','بسترن',true,0),
('بستیون','Bestune','bestune','بستیون',true,0),
('بنز','Mercedes-Benz','mercedes-benz','بنز',true,0)
ON CONFLICT (normalized_name) DO UPDATE SET name_fa=EXCLUDED.name_fa,name_en=EXCLUDED.name_en,slug=EXCLUDED.slug,is_active=true,updated_at=now();

